document.querySelector("#batch38 .grid").insertAdjacentHTML("beforeend","<a class=\"card\" href=\"summaries/paranormal-special1.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف في كهوف دراجوسان : الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا) 1\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة · غير متاح حاليا</span><h3>في كهوف دراجوسان : الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا) 1</h3><p>تصف النبذة كهوف دراجوسان كقصة تقترب من اللعبة، يكون مصير رفعت فيها مرتبطا باختيارات القارئ. وتلفت إلى إمكان العودة للكتاب مع بقاء صفحات غير مقروء…</p><small>أحمد خالد توفيق</small></a><a class=\"card\" href=\"summaries/paranormal-special2.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف 36 : الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا) 2\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة · غير متاح حاليا</span><h3>36 : الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا) 2</h3><p>تقدم النبذة رواية مرنة تسمح باختيار الرفيق ونوع الخطر والنهاية. تستعير رغبة الإنسان في الرجوع عن قراراته لتجعلها طريقة قراءة. هذه هي الفكرة التي …</p><small>أحمد خالد توفيق</small></a><a class=\"card\" href=\"summaries/sallabi-58.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف دولة السلاجقة\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">تاريخ · مجاني رسمي</span><h3>دولة السلاجقة</h3><p>تعرض المقدمة مسارا يبدأ بأصول السلاجقة واتصال الأتراك بالعالم الإسلامي، ثم قيام السلطنة وتوسعها. وتضم خطتها الصراع السياسي والعسكري والتعليم والإ…</p><small>علي محمد محمد الصلابي</small></a>");
